-- ADR 0087 lot c (SEC-16): the hourly job that asks a creator's next script reads the library, moves her queue and
-- writes her cadence in her creator under the app role (withTenantJob, app.job = 'ask_scripts'), no longer as the
-- service role, which loses these writes. No account's session sets app.job.
CREATE POLICY "job_read" ON "script_cadences" AS PERMISSIVE FOR SELECT TO public USING ("script_cadences"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'ask_scripts');--> statement-breakpoint
CREATE POLICY "job_insert" ON "script_cadences" AS PERMISSIVE FOR INSERT TO public WITH CHECK ("script_cadences"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'ask_scripts' and "script_cadences"."updated_by" is null);--> statement-breakpoint
CREATE POLICY "job_update" ON "script_cadences" AS PERMISSIVE FOR UPDATE TO public USING ("script_cadences"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'ask_scripts') WITH CHECK ("script_cadences"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'ask_scripts');--> statement-breakpoint
CREATE POLICY "job_read" ON "script_structure_queue" AS PERMISSIVE FOR SELECT TO public USING ("script_structure_queue"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'ask_scripts');--> statement-breakpoint
CREATE POLICY "job_delete" ON "script_structure_queue" AS PERMISSIVE FOR DELETE TO public USING ("script_structure_queue"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'ask_scripts');--> statement-breakpoint
CREATE POLICY "job_update" ON "script_structure_queue" AS PERMISSIVE FOR UPDATE TO public USING ("script_structure_queue"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'ask_scripts') WITH CHECK ("script_structure_queue"."creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid and nullif(current_setting('app.job', true), '') = 'ask_scripts');--> statement-breakpoint
CREATE POLICY "job_read" ON "script_structure_versions" AS PERMISSIVE FOR SELECT TO public USING (nullif(current_setting('app.job', true), '') = 'ask_scripts' and exists (select 1 from script_structures s where s.id = "script_structure_versions"."structure_id"
        and (s.reserved_creator_id is null or s.reserved_creator_id = nullif(current_setting('app.creator_id', true), '')::uuid)));--> statement-breakpoint
CREATE POLICY "job_read" ON "script_structures" AS PERMISSIVE FOR SELECT TO public USING (nullif(current_setting('app.job', true), '') = 'ask_scripts' and ("script_structures"."reserved_creator_id" is null or "script_structures"."reserved_creator_id" = nullif(current_setting('app.creator_id', true), '')::uuid));--> statement-breakpoint
-- The job moves up the structures that follow the one it asked: a right the app role did not have, opened by job_update only.
GRANT UPDATE ON "script_structure_queue" TO nirvana_app;--> statement-breakpoint
REVOKE DELETE ON "script_structure_queue" FROM impera_service;--> statement-breakpoint
REVOKE INSERT, UPDATE ON "script_cadences" FROM impera_service;
